import { test, expect } from '@playwright/test';

test.describe('Background Job Notification Toast', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/job-notification');
  });

  test('should display toast notification when background job completes successfully', async ({ page }) => {
    // Setup: Trigger background job
    const jobButton = page.getByRole('button', { name: /start job/i });
    await jobButton.click();

    // Wait for job to complete
    const jobStatus = page.getByText(/job completed/i);
    await expect(jobStatus).toBeVisible();

    // Verify toast notification appears
    const toast = page.getByRole('status');
    await expect(toast).toBeVisible();
    await expect(toast).toContainText(/job completed/i);

    // Verify success message
    const successMessage = page.getByText(/job completed successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify toast is removed after close
    await closeButton.click();
    await expect(toast).not.toBeVisible();
  });

  test('should display error toast notification when background job fails', async ({ page }) => {
    // Setup: Trigger background job
    const jobButton = page.getByRole('button', { name: /start job/i });
    await jobButton.click();

    // Simulate job failure
    await page.route('**/api/jobs/12345/status', route => {
      route.abort('failed');
    });

    // Wait for error notification
    const errorToast = page.getByRole('status');
    await expect(errorToast).toBeVisible();

    // Verify error message
    const errorMessage = page.getByText(/job failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify retry button
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify toast is removed after close
    await closeButton.click();
    await expect(errorToast).not.toBeVisible();
  });
});
